use verus::*;

// We require the input vector to be non‐empty.
// We ensure that the returned index is a valid index into `x`
// and that it points to a maximal element (no element in `x` exceeds x[res]).
#[verifier::requires(x.len() > 0)]
#[verifier::ensures(|res: usize| 
    res < x.len() 
    && forall(|j: usize| j < x.len() ==> x[j] <= x[res])
)]
fn myfun1(x: &Vec<i32>) -> usize {
    // initialize with the first element
    let mut max_index: usize = 0;
    let mut max_value: i32 = x[0];

    // iterate from 1 .. x.len()
    for (i, &value) in x.iter().enumerate().skip(1) {
        //=== loop invariants ===
        // 1) i never exceeds x.len()
        invariant!(i <= x.len());
        // 2) max_index always stays strictly below i
        invariant!(max_index < i);
        // 3) max_value is always x[max_index]
        invariant!(max_value == x[max_index]);
        // 4) max_value is the maximum among x[0..i]
        invariant!(forall(|j: usize| j < i ==> x[j] <= max_value));
        // 5) finite measure to ensure termination
        decreases!(x.len() - i);
        //=========================

        if value > max_value {
            max_value = value;
            max_index = i;
        }
    }

    max_index
}

